from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    dwarf = elf.get_dwarf_info()

    addrs = [0x2f4b20, 0x2f4c84, 0x16de04]

    for addr in addrs:
        # Use DWARF line program to find source
        found = False
        for CU in dwarf.iter_CUs():
            try:
                lp = dwarf.line_program_for_CU(CU)
                if lp is None:
                    continue
                prev_state = None
                for entry in lp.get_entries():
                    if entry.state:
                        if prev_state and prev_state.address <= addr < entry.state.address:
                            file_entry = lp['file_entry'][prev_state.file - 1]
                            dir_idx = file_entry.dir_index
                            if dir_idx > 0:
                                directory = lp['include_directory'][dir_idx - 1].decode() if isinstance(lp['include_directory'][dir_idx - 1], bytes) else lp['include_directory'][dir_idx - 1]
                            else:
                                directory = '.'
                            filename = file_entry.name.decode() if isinstance(file_entry.name, bytes) else file_entry.name
                            print(f'0x{addr:x}: {directory}/{filename}:{prev_state.line}')
                            found = True
                            break
                        prev_state = entry.state
                if found:
                    break
            except Exception:
                continue
        if not found:
            print(f'0x{addr:x}: not found in DWARF line info')
" 2>&1 | head -20

